import {
  forwardRef,
  useCallback,
  useEffect,
  useRef,
  type CSSProperties,
  type HTMLAttributes,
  type ReactNode,
} from "react";

import { useFinePointer } from "./hooks/use-fine-pointer";
import { useInheritedRadius } from "./hooks/use-inherited-radius";
import { useReducedMotion } from "./hooks/use-reduced-motion";
import { subscribePointerMove } from "./pointer-coordinator";
import { motionTokens } from "./tokens";

export interface SpotlightProps extends Omit<
  HTMLAttributes<HTMLDivElement>,
  "children"
> {
  children: ReactNode;
  /**
   * 0..1 — how strong the radial highlight is.
   * @default motionTokens.intensity.spotlight
   */
  intensity?: number;
  /** Radius of the spotlight in px. @default 220 */
  radius?: number;
  /** Disable the effect entirely (keeps the wrapper DOM). @default false */
  disabled?: boolean;
  /** Render as a different element. @default "div" */
  as?: "div" | "section" | "article" | "li" | "button";
  /**
   * How far (in px) the effect starts before the cursor reaches the element.
   * The spotlight activates when the pointer is within this distance of the
   * element's bounding box.
   * @default 0
   */
  proximity?: number;
}

/**
 * Spotlight — a pointer-following radial highlight for surfaces.
 *
 * Implementation: a window-level `pointermove` listener tracks the cursor
 * and activates the highlight when it comes within `proximity` px of the
 * element's bounding box. The highlight is an oversized radial-gradient
 * layer moved via `translate3d` on a `requestAnimationFrame`-throttled
 * callback — compositor-only motion, no per-frame repaints, and no
 * JavaScript animation loop runs while the pointer is idle.
 *
 * Reduced motion: the effect is disabled entirely. The surface remains
 * fully usable; spotlight is purely decorative.
 *
 * The gradient lives in its own clipped layer (`overflow: hidden` +
 * inherited `border-radius`), so children are never clipped — a
 * child's `box-shadow` and other overflowing paint render normally.
 */
export const Spotlight = forwardRef<HTMLDivElement, SpotlightProps>(
  function Spotlight(
    {
      children,
      intensity = motionTokens.intensity.spotlight,
      radius = 220,
      disabled = false,
      proximity = 0,
      as: Tag = "div",
      style,
      onPointerMove,
      onPointerLeave,
      ...rest
    },
    ref,
  ) {
    const reduced = useReducedMotion();
    const fine = useFinePointer();
    const frame = useRef<number | null>(null);
    // The first element child is the overlay span, so resolve the
    // content child through the trailing `display: contents` wrapper.
    const innerRef = useInheritedRadius<HTMLDivElement>({
      resolveChild: (el) =>
        (el.lastElementChild?.firstElementChild as HTMLElement | null) ?? null,
    });
    const overlayRef = useRef<HTMLSpanElement | null>(null);
    const activeRef = useRef(false);
    const rectRef = useRef<DOMRect | null>(null);

    // Pointer-driven — skipped entirely on touch devices, where hover
    // never fires and pointermove only fires during scroll gestures.
    const enabled = !disabled && !reduced && fine;

    // Cache the bounding rect and refresh on scroll/resize to avoid
    // calling getBoundingClientRect on every pointermove event.
    const refreshRect = useCallback(() => {
      const el = innerRef.current;
      if (!el) return;
      rectRef.current = el.getBoundingClientRect();
    }, [innerRef]);

    const updateSpotlight = useCallback(
      (clientX: number, clientY: number) => {
        const el = innerRef.current;
        if (!el) return;
        const rect = rectRef.current ?? el.getBoundingClientRect();
        const expandedRect = {
          left: rect.left - proximity,
          top: rect.top - proximity,
          right: rect.right + proximity,
          bottom: rect.bottom + proximity,
        };
        const inside =
          clientX >= expandedRect.left &&
          clientX <= expandedRect.right &&
          clientY >= expandedRect.top &&
          clientY <= expandedRect.bottom;

        if (frame.current != null) cancelAnimationFrame(frame.current);
        frame.current = requestAnimationFrame(() => {
          const ov = overlayRef.current;
          if (!ov) return;
          if (inside) {
            // The overlay is a 200% layer whose gradient is centered at
            // the element's center at rest — translating it by the
            // pointer offset lands the highlight under the cursor while
            // staying on compositor properties (no per-frame repaint).
            const x = clientX - rect.left - rect.width / 2;
            const y = clientY - rect.top - rect.height / 2;
            ov.style.transform = `translate3d(${x}px, ${y}px, 0)`;
            const target = String(intensity);
            if (ov.style.opacity !== target) ov.style.opacity = target;
            activeRef.current = true;
          } else if (activeRef.current) {
            ov.style.opacity = "0";
            activeRef.current = false;
          }
          frame.current = null;
        });
      },
      [intensity, proximity, innerRef],
    );

    useEffect(() => {
      if (!enabled) return;
      refreshRect();
      const unsubscribe = subscribePointerMove(updateSpotlight);
      window.addEventListener("scroll", refreshRect, { passive: true });
      window.addEventListener("resize", refreshRect, { passive: true });
      return () => {
        unsubscribe();
        window.removeEventListener("scroll", refreshRect);
        window.removeEventListener("resize", refreshRect);
        if (frame.current != null) cancelAnimationFrame(frame.current);
      };
    }, [enabled, updateSpotlight, refreshRect]);

    const handlePointerMove = useCallback(
      (e: React.PointerEvent<HTMLDivElement>) => {
        onPointerMove?.(e);
      },
      [onPointerMove],
    );

    const handlePointerLeave = useCallback(
      (e: React.PointerEvent<HTMLDivElement>) => {
        onPointerLeave?.(e);
      },
      [onPointerLeave],
    );

    const surfaceStyle: CSSProperties = {
      position: "relative",
      isolation: "isolate",
      ...style,
    };

    const Comp = Tag as "div";

    return (
      <Comp
        {...rest}
        ref={(node: HTMLDivElement | null) => {
          innerRef.current = node;
          if (typeof ref === "function") ref(node);
          else if (ref) ref.current = node;
        }}
        style={surfaceStyle}
        onPointerMove={handlePointerMove}
        onPointerLeave={handlePointerLeave}
      >
        {enabled && (
          // Clip layer, not the wrapper: the gradient stays inside the
          // rounded bounds (radius inherited via `useInheritedRadius`)
          // while the child's own box-shadow can still paint outside.
          <span
            aria-hidden="true"
            style={{
              position: "absolute",
              inset: 0,
              borderRadius: "inherit",
              overflow: "hidden",
              pointerEvents: "none",
              zIndex: 0,
            }}
          >
            <span
              ref={overlayRef}
              style={{
                position: "absolute",
                // 200% layer: its center coincides with the element's
                // center, so translate3d(pointer-offset) places the
                // static gradient under the cursor — compositor-only
                // motion.
                inset: "-50%",
                opacity: 0,
                transition: `opacity ${motionTokens.duration.fast}ms var(--ease-standard, cubic-bezier(${motionTokens.easing.standard.join(", ")}))`,
                willChange: "transform, opacity",
                background: `radial-gradient(${radius}px circle at center, color-mix(in oklab, var(--accent, oklch(0.82 0.16 220)) 18%, transparent), transparent 70%)`,
              }}
            />
          </span>
        )}
        <span style={{ position: "relative", zIndex: 1, display: "contents" }}>
          {children}
        </span>
      </Comp>
    );
  },
);

import { useEffect, useState } from "react";

/**
 * Returns `true` when the user has requested reduced motion via the OS / browser.
 *
 * All Ionbit UI motion primitives use this to self-disable. Components should
 * never animate transform/opacity in a way that distracts under reduced motion.
 */
export function useReducedMotion(): boolean {
  const [reduced, setReduced] = useState<boolean>(() => {
    if (typeof window === "undefined" || !window.matchMedia) return false;
    return window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  });

  useEffect(() => {
    if (typeof window === "undefined" || !window.matchMedia) return;
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    const handler = (e: MediaQueryListEvent) => setReduced(e.matches);
    mq.addEventListener("change", handler);
    return () => mq.removeEventListener("change", handler);
  }, []);

  return reduced;
}

import {
  useCallback,
  useEffect,
  useLayoutEffect,
  useRef,
  type MutableRefObject,
} from "react";

import { observeStyleChanges } from "../style-observer";

export interface UseInheritedRadiusOptions<T extends HTMLElement> {
  /**
   * Resolve the element whose computed border-radius should be
   * mirrored. Defaults to the wrapper's `firstElementChild` — override
   * when the wrapper's DOM contains non-content siblings (e.g.
   * overlay layers) before the real content.
   */
  resolveChild?: (el: T) => HTMLElement | null;
}

/**
 * Reads the content child's computed border-radius and applies it to
 * the wrapper element. This lets motion wrappers (Glow, Pulse,
 * Spotlight, Tilt, Ripple) automatically match the wrapped element's
 * rounded corners without requiring the user to pass a `className`
 * for the radius.
 *
 * The radius is sampled lazily on the first commit where the wrapper
 * element actually exists — primitives that drop their wrapper while
 * `disabled` mount it only once the effect turns on, so a one-shot
 * mount-time sample would leave them radius-less. Re-sampled when the
 * document's styles change (injected stylesheets, root attribute/class
 * changes — e.g. theme switches) and on `pointerenter`, so live theme
 * updates don't require a reload.
 *
 * @returns A ref to attach to the wrapper element.
 */
export function useInheritedRadius<T extends HTMLElement = HTMLElement>(
  options?: UseInheritedRadiusOptions<T>,
): MutableRefObject<T | null> {
  const ref = useRef<T | null>(null);
  const optionsRef = useRef(options);
  optionsRef.current = options;
  // Pending-sample flag — kept true until the wrapper exists, so a
  // late-mounted wrapper (disabled → enabled) still gets sampled.
  const dirty = useRef(true);

  const sample = useCallback(() => {
    const el = ref.current;
    if (!el) return;
    const child = (optionsRef.current?.resolveChild?.(el) ??
      el.firstElementChild) as HTMLElement | null;
    if (!child) return;

    const childRadius = getComputedStyle(child).borderRadius;
    if (childRadius && el.style.borderRadius !== childRadius) {
      el.style.borderRadius = childRadius;
    }
  }, []);

  // Runs after every commit but only samples while one is pending —
  // covers wrappers mounted by a disabled→enabled flip, and applies
  // the radius before paint on the initial mount.
  useLayoutEffect(() => {
    if (!dirty.current || !ref.current) return;
    dirty.current = false;
    sample();
  });

  useEffect(
    () =>
      observeStyleChanges(ref.current ?? document.documentElement, () => {
        dirty.current = true;
        sample();
      }),
    [sample],
  );

  return ref;
}

/**
 * Samples the wrapped element's computed text color — the "ink" that
 * reads correctly on any solid background. Used by Ripple (ripple
 * color) and Tilt (reflection glare) so effects follow the element's
 * own foreground on both light and dark surfaces.
 *
 * Reads `firstElementChild` (the wrapped content), falling back to
 * the wrapper itself, and returns `fallback` when the computed color
 * is empty or fully transparent.
 */
export function sampleInkColor(
  el: HTMLElement,
  fallback = "currentColor",
): string {
  const target = (el.firstElementChild ?? el) as HTMLElement;
  const computed = getComputedStyle(target).color;
  return computed && computed !== "transparent" ? computed : fallback;
}

/**
 * Invokes `callback` whenever the document's styles could have changed:
 * injected/replaced stylesheets in `<head>`, attribute/class mutations
 * on the root element (e.g. `.dark` mode toggles, theme classes), and
 * on `pointerenter` of `el` as a fallback for class-driven style
 * changes the document observers cannot see.
 *
 * Used by primitives that sample computed styles (inherited radius,
 * inherited text color) so live theme updates don't require a reload.
 *
 * @returns A cleanup function that disconnects all listeners.
 */
export function observeStyleChanges(
  el: HTMLElement,
  callback: () => void,
): () => void {
  const observer = new MutationObserver(callback);
  observer.observe(document.head, {
    childList: true,
    characterData: true,
    subtree: true,
  });
  observer.observe(document.documentElement, { attributes: true });
  el.addEventListener("pointerenter", callback);

  return () => {
    observer.disconnect();
    el.removeEventListener("pointerenter", callback);
  };
}

// Single global pointer-move listener that broadcasts to all registered
// subscribers. Avoids N separate window-level listeners when multiple
// Magnetic/Spotlight instances are on the page.

type PointerHandler = (clientX: number, clientY: number) => void;

const subscribers = new Set<PointerHandler>();
let listener: ((e: PointerEvent) => void) | null = null;

function ensureListener() {
  if (listener || typeof window === "undefined") return;
  listener = (e: PointerEvent) => {
    for (const handler of subscribers) {
      handler(e.clientX, e.clientY);
    }
  };
  window.addEventListener("pointermove", listener, { passive: true });
}

function maybeRemoveListener() {
  if (subscribers.size > 0 || !listener) return;
  window.removeEventListener("pointermove", listener);
  listener = null;
}

export function subscribePointerMove(handler: PointerHandler): () => void {
  subscribers.add(handler);
  ensureListener();
  return () => {
    subscribers.delete(handler);
    maybeRemoveListener();
  };
}

/**
 * Ionbit UI — Motion tokens
 *
 * The single source of truth for timing, easing, spring, and intensity.
 * Components and primitives reference these; they do not hardcode values.
 *
 * These mirror the CSS variables in @ionbit-ui/tokens so JS-driven
 * animations (Motion) and CSS-driven animations stay in sync.
 */

export const motionTokens = {
  duration: {
    fast: 140,
    normal: 220,
    slow: 420,
  },
  easing: {
    standard: [0.2, 0.8, 0.2, 1] as const,
    emphasized: [0.3, 0, 0, 1] as const,
    exit: [0.4, 0, 1, 1] as const,
  },
  spring: {
    magnetic: { stiffness: 200, damping: 15, mass: 0.3 },
    gentle: { stiffness: 120, damping: 20, mass: 0.4 },
  },
  intensity: {
    glow: 0.7,
    magnetic: 0.2,
    pulse: 0.65,
    ripple: 0.3,
    scramble: 0.6,
    spotlight: 0.4,
    tilt: 0.5,
    tiltReflection: 0.35,
    trace: 0.6,
  },
} as const;

export type MotionTokens = typeof motionTokens;
